\path[use as bounding box] (-5,-3.5) rectangle (3.5,3.5);
\draw[black,line width=0.5pt,->] (-4.8,0)--(3.2,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-3.2)--(0,3.2) node[above] {$y$};
